mapper.select:
select t.machine_id machineId,t.machine_code machineCode,t.collect_id collectId,t.status_cd
statusCd,t.community_id communityId,t.machine_name machineName,t.staff_id staffId,t.create_time createTime
from monitor_collect t
where 1 =1

    and t.machine_id= #{machineId}


    and t.machine_code= #{machineCode}


    and t.collect_id= #{collectId}


    and t.status_cd= #{statusCd}


    and t.community_id= #{communityId}


    and t.machine_name= #{machineName}


    and t.staff_id= #{staffId}

order by t.create_time desc

    limit #{page}, #{row}

